                              {report.pet_breed && (
                                <p className="text-sm text-gray-600">
                                  <span className="font-semibold">Breed:</span>{" "}
                                  {report.pet_breed}
                                </p>
                              )}
                              {report.pet_location && (
                                <p className="text-sm text-gray-600 flex items-center gap-1">
                                  <span>📍</span>
                                  <span className="font-semibold">
