                              <button
                                onClick={() => fetchPetDetails(report.pet_id)}
                                className="mt-3 w-full px-4 py-3 bg-gradient-to-r from-blue-500 via-blue-600 to-blue-700 text-white font-bold rounded-xl hover:shadow-lg hover:scale-105 transition-all duration-200 flex items-center justify-center gap-2"
                              >
                                <span className="text-lg">👁️</span>
                                View Full Details
                              </button>
                            )}
                          </div>
                        </div>
                      ))
